content:
{
  "components": {
    "schemas": {
      "ActionPlan": {
        "additionalProperties": false,
        "properties": {
          "actions": {
            "items": {
              "$ref": "#/components/schemas/EvaluatedAction"
            },
            "maxItems": 10,
            "minItems": 1,
            "title": "Actions",
            "type": "array"
          },
          "conclusion_evidence_id": {
            "format": "uuid",
            "title": "Conclusion Evidence Id",
            "type": "string"
          },
          "environment": {
            "$ref": "#/components/schemas/PolicyEnvironment"
          },
          "planning_version": {
            "minimum": 1.0,
            "title": "Planning Version",
            "type": "integer"
          },
          "review_evidence_id": {
            "format": "uuid",
            "title": "Review Evidence Id",
            "type": "string"
          },
          "runbook": {
            "anyOf": [
              {
                "$ref": "#/components/schemas/RunbookPolicyContext"
              },
              {
                "type": "null"
              }
            ]
          },
          "summary": {
            "$ref": "#/components/schemas/EvidenceClaim"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          }
        },
        "required": [
          "task_id",
          "planning_version",
          "conclusion_evidence_id",
          "review_evidence_id",
          "environment",
          "summary",
          "actions"
        ],
        "title": "ActionPlan",
        "type": "object"
      },
      "AnswerInput": {
        "additionalProperties": false,
        "properties": {
          "answer": {
            "maxLength": 8000,
            "minLength": 1,
            "title": "Answer",
            "type": "string"
          },
          "question_id": {
            "format": "uuid",
            "title": "Question Id",
            "type": "string"
          },
          "wait_version": {
            "minimum": 1.0,
            "title": "Wait Version",
            "type": "integer"
          }
        },
        "required": [
          "question_id",
          "wait_version",
          "answer"
        ],
        "title": "AnswerInput",
        "type": "object"
      },
      "ApprovalInput": {
        "additionalProperties": false,
        "properties": {
          "action_hash": {
            "pattern": "^[0-9a-f]{64}$",
            "title": "Action Hash",
            "type": "string"
          },
          "approval_id": {
            "format": "uuid",
            "title": "Approval Id",
            "type": "string"
          },
          "decision": {
            "enum": [
              "approved",
              "rejected"
            ],
            "title": "Decision",
            "type": "string"
          },
          "wait_version": {
            "minimum": 1.0,
            "title": "Wait Version",
            "type": "integer"
          }
        },
        "required": [
          "approval_id",
          "wait_version",
          "action_hash",
          "decision"
        ],
        "title": "ApprovalInput",
        "type": "object"
      },
      "ApprovalTicket": {
        "additionalProperties": false,
        "properties": {
          "action_hash": {
            "pattern": "^[0-9a-f]{64}$",
            "title": "Action Hash",
            "type": "string"
          },
          "approval_id": {
            "format": "uuid",
            "title": "Approval Id",
            "type": "string"
          },
          "plan": {
            "$ref": "#/components/schemas/ActionPlan"
          },
          "plan_evidence_id": {
            "format": "uuid",
            "title": "Plan Evidence Id",
            "type": "string"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          },
          "wait_version": {
            "minimum": 1.0,
            "title": "Wait Version",
            "type": "integer"
          }
        },
        "required": [
          "approval_id",
          "task_id",
          "wait_version",
          "plan_evidence_id",
          "action_hash",
          "plan"
        ],
        "title": "ApprovalTicket",
        "type": "object"
      },
      "AuditEventType": {
        "enum": [
          "tool_call",
          "state_transition",
          "approval",
          "execution",
          "human_interaction"
        ],
        "title": "AuditEventType",
        "type": "string"
      },
      "AuditView": {
        "additionalProperties": false,
        "properties": {
          "actor": {
            "title": "Actor",
            "type": "string"
          },
          "details": {
            "additionalProperties": {
              "$ref": "#/components/schemas/JsonValue"
            },
            "title": "Details",
            "type": "object"
          },
          "event_type": {
            "anyOf": [
              {
                "$ref": "#/components/schemas/AuditEventType"
              },
              {
                "const": "catalog_edit",
                "type": "string"
              }
            ],
            "title": "Event Type"
          },
          "evidence_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Evidence Id"
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "occurred_at": {
            "format": "date-time",
            "title": "Occurred At",
            "type": "string"
          },
          "operation": {
            "title": "Operation",
            "type": "string"
          },
          "outcome": {
            "title": "Outcome",
            "type": "string"
          },
          "task_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Task Id"
          }
        },
        "required": [
          "id",
          "task_id",
          "event_type",
          "actor",
          "operation",
          "outcome",
          "evidence_id",
          "details",
          "occurred_at"
        ],
        "title": "AuditView",
        "type": "object"
      },
      "AutomationLevel": {
        "enum": [
          "manual",
          "semi_automated",
          "approval_automated",
          "self_healing"
        ],
        "title": "AutomationLevel",
        "type": "string"
      },
      "ChangeEntryView": {
        "additionalProperties": false,
        "properties": {
          "created_at": {
            "format": "date-time",
            "title": "Created At",
            "type": "string"
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "kind": {
            "title": "Kind",
            "type": "string"
          },
          "occurred_at": {
            "format": "date-time",
            "title": "Occurred At",
            "type": "string"
          },
          "revision": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Revision"
          },
          "service_name": {
            "title": "Service Name",
            "type": "string"
          },
          "source": {
            "title": "Source",
            "type": "string"
          },
          "source_ref": {
            "title": "Source Ref",
            "type": "string"
          }
        },
        "required": [
          "id",
          "service_name",
          "source",
          "kind",
          "source_ref",
          "revision",
          "occurred_at",
          "created_at"
        ],
        "title": "ChangeEntryView",
        "type": "object"
      },
      "ChatAnswer": {
        "additionalProperties": false,
        "properties": {
          "answer": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Answer"
          },
          "conclusion_evidence_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Conclusion Evidence Id"
          },
          "evidence_ids": {
            "default": [],
            "items": {
              "format": "uuid",
              "type": "string"
            },
            "title": "Evidence Ids",
            "type": "array"
          },
          "pending": {
            "title": "Pending",
            "type": "boolean"
          },
          "plan_evidence_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Plan Evidence Id"
          },
          "policy_decision": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Policy Decision"
          },
          "review_evidence_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Review Evidence Id"
          },
          "status": {
            "title": "Status",
            "type": "string"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          }
        },
        "required": [
          "task_id",
          "status",
          "pending"
        ],
        "title": "ChatAnswer",
        "type": "object"
      },
      "ChatInput": {
        "additionalProperties": false,
        "properties": {
          "end": {
            "anyOf": [
              {
                "format": "date-time",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "End"
          },
          "message": {
            "maxLength": 4000,
            "minLength": 1,
            "title": "Message",
            "type": "string"
          },
          "mode": {
            "default": "question",
            "enum": [
              "question",
              "task"
            ],
            "title": "Mode",
            "type": "string"
          },
          "previous_task_id": {
            "anyOf": [
              {
                "format": "uuid",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Previous Task Id"
          },
          "request_id": {
            "format": "uuid",
            "title": "Request Id",
            "type": "string"
          },
          "service_name": {
            "pattern": "^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$",
            "title": "Service Name",
            "type": "string"
          },
          "start": {
            "anyOf": [
              {
                "format": "date-time",
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Start"
          }
        },
        "required": [
          "request_id",
          "service_name",
          "message"
        ],
        "title": "ChatInput",
        "type": "object"
      },
      "ControlReceipt": {
        "additionalProperties": false,
        "properties": {
          "evidence_id": {
            "format": "uuid",
            "title": "Evidence Id",
            "type": "string"
          },
          "operation_id": {
            "title": "Operation Id",
            "type": "string"
          },
          "outcome": {
            "enum": [
              "signaled",
              "taken_over"
            ],
            "title": "Outcome",
            "type": "string"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          }
        },
        "required": [
          "task_id",
          "operation_id",
          "evidence_id",
          "outcome"
        ],
        "title": "ControlReceipt",
        "type": "object"
      },
      "DiagnosticStep": {
        "additionalProperties": false,
        "properties": {
          "description": {
            "maxLength": 4000,
            "minLength": 1,
            "title": "Description",
            "type": "string"
          },
          "parameters": {
            "additionalProperties": {
              "$ref": "#/components/schemas/JsonValue"
            },
            "title": "Parameters",
            "type": "object"
          },
          "risk_level": {
            "const": "L0",
            "title": "Risk Level",
            "type": "string"
          },
          "tool_name": {
            "pattern": "^[a-z][a-z0-9_]{0,127}$",
            "title": "Tool Name",
            "type": "string"
          }
        },
        "required": [
          "description",
          "tool_name",
          "parameters",
          "risk_level"
        ],
        "title": "DiagnosticStep",
        "type": "object"
      },
      "EdgeView": {
        "additionalProperties": false,
        "properties": {
          "confidence": {
            "title": "Confidence",
            "type": "number"
          },
          "first_seen": {
            "format": "date-time",
            "title": "First Seen",
            "type": "string"
          },
          "freshness_seconds": {
            "title": "Freshness Seconds",
            "type": "number"
          },
          "from_node_id": {
            "format": "uuid",
            "title": "From Node Id",
            "type": "string"
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "last_seen": {
            "format": "date-time",
            "title": "Last Seen",
            "type": "string"
          },
          "relation": {
            "title": "Relation",
            "type": "string"
          },
          "source": {
            "title": "Source",
            "type": "string"
          },
          "to_node_id": {
            "format": "uuid",
            "title": "To Node Id",
            "type": "string"
          }
        },
        "required": [
          "id",
          "from_node_id",
          "to_node_id",
          "relation",
          "source",
          "confidence",
          "first_seen",
          "last_seen",
          "freshness_seconds"
        ],
        "title": "EdgeView",
        "type": "object"
      },
      "EvaluatedAction": {
        "additionalProperties": false,
        "properties": {
          "action": {
            "$ref": "#/components/schemas/PlannedAction"
          },
          "policy": {
            "$ref": "#/components/schemas/PolicyResult"
          }
        },
        "required": [
          "action",
          "policy"
        ],
        "title": "EvaluatedAction",
        "type": "object"
      },
      "EventReceipt": {
        "properties": {
          "duplicate": {
            "title": "Duplicate",
            "type": "boolean"
          },
          "event_id": {
            "title": "Event Id",
            "type": "string"
          },
          "task_id": {
            "title": "Task Id",
            "type": "string"
          },
          "workflow_id": {
            "title": "Workflow Id",
            "type": "string"
          }
        },
        "required": [
          "event_id",
          "task_id",
          "workflow_id",
          "duplicate"
        ],
        "title": "EventReceipt",
        "type": "object"
      },
      "EventView": {
        "additionalProperties": false,
        "properties": {
          "created_at": {
            "format": "date-time",
            "title": "Created At",
            "type": "string"
          },
          "external_id": {
            "title": "External Id",
            "type": "string"
          },
          "fingerprint": {
            "title": "Fingerprint",
            "type": "string"
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "occurred_at": {
            "format": "date-time",
            "title": "Occurred At",
            "type": "string"
          },
          "origin": {
            "title": "Origin",
            "type": "string"
          },
          "service_name": {
            "title": "Service Name",
            "type": "string"
          },
          "source": {
            "$ref": "#/components/schemas/TaskSource"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          },
          "title": {
            "title": "Title",
            "type": "string"
          }
        },
        "required": [
          "id",
          "task_id",
          "origin",
          "source",
          "external_id",
          "service_name",
          "title",
          "fingerprint",
          "occurred_at",
          "created_at"
        ],
        "title": "EventView",
        "type": "object"
      },
      "EvidenceClaim": {
        "additionalProperties": false,
        "properties": {
          "evidence_ids": {
            "items": {
              "format": "uuid",
              "type": "string"
            },
            "maxItems": 100,
            "minItems": 1,
            "title": "Evidence Ids",
            "type": "array"
          },
          "statement": {
            "maxLength": 4000,
            "minLength": 1,
            "title": "Statement",
            "type": "string"
          }
        },
        "required": [
          "statement",
          "evidence_ids"
        ],
        "title": "EvidenceClaim",
        "type": "object"
      },
      "EvidenceView": {
        "additionalProperties": false,
        "properties": {
          "collected_at": {
            "format": "date-time",
            "title": "Collected At",
            "type": "string"
          },
          "created_at": {
            "format": "date-time",
            "title": "Created At",
            "type": "string"
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "parameters": {
            "additionalProperties": {
              "$ref": "#/components/schemas/JsonValue"
            },
            "title": "Parameters",
            "type": "object"
          },
          "result_snapshot": {
            "anyOf": [
              {
                "$ref": "#/components/schemas/JsonValue"
              },
              {
                "type": "null"
              }
            ]
          },
          "source_reference": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "title": "Source Reference"
          },
          "source_tool": {
            "title": "Source Tool",
            "type": "string"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          }
        },
        "required": [
          "id",
          "task_id",
          "source_tool",
          "parameters",
          "result_snapshot",
          "source_reference",
          "collected_at",
          "created_at"
        ],
        "title": "EvidenceView",
        "type": "object"
      },
      "GraphContext": {
        "additionalProperties": false,
        "properties": {
          "as_of": {
            "format": "date-time",
            "title": "As Of",
            "type": "string"
          },
          "edges": {
            "items": {
              "$ref": "#/components/schemas/EdgeView"
            },
            "title": "Edges",
            "type": "array"
          },
          "nodes": {
            "items": {
              "$ref": "#/components/schemas/NodeView"
            },
            "title": "Nodes",
            "type": "array"
          },
          "service_name": {
            "maxLength": 256,
            "minLength": 1,
            "pattern": "^\\S+$",
            "title": "Service Name",
            "type": "string"
          }
        },
        "required": [
          "service_name",
          "as_of",
          "nodes",
          "edges"
        ],
        "title": "GraphContext",
        "type": "object"
      },
      "HTTPValidationError": {
        "properties": {
          "detail": {
            "items": {
              "$ref": "#/components/schemas/ValidationError"
            },
            "title": "Detail",
            "type": "array"
          }
        },
        "title": "HTTPValidationError",
        "type": "object"
      },
      "HandlingStep": {
        "additionalProperties": false,
        "properties": {
          "description": {
            "maxLength": 4000,
            "minLength": 1,
            "title": "Description",
            "type": "string"
          },
          "risk_level": {
            "$ref": "#/components/schemas/RiskLevel"
          }
        },
        "required": [
          "description",
          "risk_level"
        ],
        "title": "HandlingStep",
        "type": "object"
      },
      "HealthResponse": {
        "properties": {
          "status": {
            "const": "ok",
            "default": "ok",
            "title": "Status",
            "type": "string"
          }
        },
        "title": "HealthResponse",
        "type": "object"
      },
      "HistoryView": {
        "additionalProperties": false,
        "properties": {
          "actor": {
            "title": "Actor",
            "type": "string"
          },
          "changed_at": {
            "format": "date-time",
            "title": "Changed At",
            "type": "string"
          },
          "from_status": {
            "anyOf": [
              {
                "$ref": "#/components/schemas/TaskStatus"
              },
              {
                "type": "null"
              }
            ]
          },
          "id": {
            "format": "uuid",
            "title": "Id",
            "type": "string"
          },
          "reason": {
            "title": "Reason",
            "type": "string"
          },
          "sequence": {
            "title": "Sequence",
            "type": "integer"
          },
          "task_id": {
            "format": "uuid",
            "title": "Task Id",
            "type": "string"
          },
          "to_status": {
            "$ref": "#/components/schemas/TaskStatus"
          }
        },
        "required": [
          "id",
          "task_id",
          "sequence",
          "from_status",
          "to_status",
          "reason",
          "actor",
          "changed_at"
        ],
        "title": "HistoryView",
        "type": "object"
      },
      "HumanPrompt": {
        "properties": {
          "question": {
            "title": "Question",
            "type": "string"
          },
          "question_evidence_id": {
            "title": "Question Evidence Id",
            "type": "string"
          },
          "question_id": {
            "title": "Question Id",
            "type": "string"
          },
          "resume_status": {
            "$ref": "#/components/schemas/TaskStatus"
          },
          "task": {
            "$ref": "#/components/schemas/TaskSnapshot"
          }
        },
        "required": [
          "task",
          "question_id",
          "question_evidence_id",
          "question",
          "resume_status"
        ],
        "title": "HumanPrompt",
        "type": "object"
      },
      "HumanWaitRequest": {
        "properties": {
          "question": {
            "title": "Question",
            "type": "string"
          },
          "resume_status": {
            "$ref": "#/components/schemas/TaskStatus"
          },
          "task": {
            "$ref": "#/components/schemas/TaskSnapshot"
          }
        },
        "required": [
          "task",
          "question",
          "resume_status"
        ],
        "title": "HumanWaitRequest",
        "type": "object"
      },
      "IncidentHit": {
        "additionalProperties": false,
        "properties": {
          "evidence_id": {
            "format": "uuid",
            "title": "Evidence Id",
            "type": "string"
          },
          "report": {
            "$ref": "#/components/schemas/IncidentReport"
          }
        },
        "required": [
          "evidence_id",
          "report"
        ],
        "title": "IncidentHit",
        "type": "object"
      },
      "IncidentReport": {
        "additionalProperties": false,
        "properties": {
          "improvement_task_ids": {
            "items": {
              "format": "uuid",
              "type": "string"
            },
            "minItems": 1,
            "title": "Improvement Task Ids",
            "type": "array"
          },
          "improvements": {
            "items": {
              "$ref": "#/components/schemas/EvidenceClaim"
            },
            "maxItems": 10,
            "minItems": 1,
            "title": "Improvements",
            "type": "array"
          },
          "runbook_id": {
            "format": "uuid",
            "title": "Runbook Id",
            "type": "string"
          },
